() => {
  const r = {};
  r.ready = window.__ready;
  r.fontLoaded = document.fonts.check('700 60px Inter');
  const card = document.querySelector('.card');
  const cb = card.getBoundingClientRect();
  r.card = [cb.width, cb.height];
  r.cardScroll = [card.scrollWidth, card.scrollHeight];
  const inner = document.getElementById('inner');
  r.innerScroll = [inner.scrollWidth, inner.scrollHeight, inner.clientHeight];
  r.items = [...document.querySelectorAll('.brand,.who,.avatar,.name,.role,.title,.foot,.when,.btn')].map(e=>{
    const b = e.getBoundingClientRect();
    return e.className+' :: '+[b.x,b.y,b.width,b.height].map(n=>Math.round(n)).join(',')+' | bottom='+Math.round(b.bottom)+' right='+Math.round(b.right);
  });
  // avatar computed
  const av = document.querySelector('.avatar');
  r.avatarBox = av ? [av.offsetWidth, av.offsetHeight] : null;
  return r;
}

