() => {
  const card = document.querySelector('.card');
  const cs = getComputedStyle(card);
  const pad = {t:parseFloat(cs.paddingTop),r:parseFloat(cs.paddingRight),b:parseFloat(cs.paddingBottom),l:parseFloat(cs.paddingLeft)};
  const cb = card.getBoundingClientRect();
  const safe = {l:cb.left+pad.l-0.6, t:cb.top+pad.t-0.6, r:cb.right-pad.r+0.6, b:cb.bottom-pad.b+0.6};
  const out=[];
  document.querySelectorAll('.inner *').forEach(e=>{
    const b=e.getBoundingClientRect();
    if(b.width===0&&b.height===0) return;
    const bad=[];
    if(b.left<safe.l)bad.push('L'+(safe.l-b.left).toFixed(1));
    if(b.top<safe.t)bad.push('T'+(safe.t-b.top).toFixed(1));
    if(b.right>safe.r)bad.push('R'+(b.right-safe.r).toFixed(1));
    if(b.bottom>safe.b)bad.push('B'+(b.bottom-safe.b).toFixed(1));
    if(e.scrollWidth>e.clientWidth+1 && getComputedStyle(e).overflow!=='visible')bad.push('scrollX');
    if(bad.length)out.push(e.className+' -> '+bad.join(' '));
  });
  const g=s=>{const e=document.querySelector(s);if(!e)return null;const b=e.getBoundingClientRect();return {y:Math.round(b.top),b:Math.round(b.bottom),w:Math.round(b.width),h:Math.round(b.height)};};
  return {ready:window.__ready, overflow:out,
    ratios:{avatar:(()=>{const a=document.querySelector('.avatar');return a.offsetWidth+'x'+a.offsetHeight;})()},
    boxes:{brand:g('.brand'),who:g('.who'),title:g('.title'),hr:g('.hr'),foot:g('.foot'),btn:g('.btn'),when:g('.when')},
    titleLines: Math.round(g('.title').h / (parseFloat(getComputedStyle(document.querySelector('.title')).lineHeight)))
  };
}

